<script setup>
import {computed,reactive,ref,watch} from 'vue'
import {supplementApi} from '../api/enhancements.js'
const props=defineProps({resource:{type:Object,required:true},scope:{type:String,default:'teacher'}})
const editable=computed(()=>props.scope==='teacher'&&['DRAFT','REJECTED'].includes(props.resource.status))
const data=reactive({originalAuthor:'',sourceNote:'',usageRights:''}),meta=ref(null),error=ref(''),busy=ref(false),stamp=ref(0)
let sequence=0
async function load(){const current=++sequence,id=props.resource.id;try{const m=await supplementApi.read(id,props.scope);if(current!==sequence)return;meta.value=m;for(const k of Object.keys(data))data[k]=m[k]||'';stamp.value=Date.now()}catch(e){if(current===sequence)error.value=e.message}}
watch(()=>[props.resource.id,props.scope],()=>{meta.value=null;error.value='';load()},{immediate:true})
async function run(action){if(busy.value)return;busy.value=true;error.value='';try{await action();await load()}catch(e){error.value=e.message}finally{busy.value=false}}
function upload(event){const file=event.target.files?.[0];if(file)run(()=>supplementApi.cover(props.resource.id,file));event.target.value=''}
const coverUrl=computed(()=>`/api/${props.scope==='teacher'?'teacher/resources':props.scope==='review'?'admin/resource-reviews':'resources'}/${props.resource.id}/cover?v=${stamp.value}`)
</script>
<template><section class="metadata-panel"><h2>资源封面与来源说明</h2><p class="field-hint">说明由资源提供者填写；系统内可访问不等于取得复制、改编或外部传播许可。</p><p v-if="error" class="message error" role="alert">{{error}}</p><template v-if="meta"><div v-if="meta.hasCover" class="cover-editor"><img :src="coverUrl" alt="教学资源封面"/><button v-if="editable" class="secondary" :disabled="busy" @click="run(()=>supplementApi.removeCover(resource.id))">移除封面</button></div><template v-if="editable"><label :for="`cover-file-${resource.id}`">设置可选封面（PNG/JPEG，≤2MiB）</label><input :id="`cover-file-${resource.id}`" type="file" accept="image/png,image/jpeg" :disabled="busy" @change="upload"/><form @submit.prevent="run(()=>supplementApi.save(resource.id,{...data}))"><label :for="`author-${resource.id}`">原作者或提供单位</label><input :id="`author-${resource.id}`" v-model="data.originalAuthor" maxlength="120" :disabled="busy"/><label :for="`source-${resource.id}`">出处或来源链接（文本说明）</label><textarea :id="`source-${resource.id}`" v-model="data.sourceNote" maxlength="1000" :disabled="busy"/><label :for="`rights-${resource.id}`">使用许可或限制说明</label><textarea :id="`rights-${resource.id}`" v-model="data.usageRights" maxlength="1000" :disabled="busy"/><button class="secondary" :disabled="busy">保存来源说明</button></form></template><dl v-else><dt>原作者或提供单位</dt><dd>{{meta.originalAuthor||'未提供'}}</dd><dt>出处或来源</dt><dd>{{meta.sourceNote||'未提供'}}</dd><dt>使用说明</dt><dd>{{meta.usageRights||'未提供，请勿自行推定授权范围。'}}</dd></dl></template><p v-else class="muted">正在读取来源说明…</p></section></template>
<style scoped>.metadata-panel{margin:25px 0;padding:22px 0;border-top:1px solid var(--line)}.metadata-panel h2{font-size:17px}.metadata-panel textarea{min-height:75px}.metadata-panel form{max-width:760px}.metadata-panel dd{margin:5px 0 15px;white-space:pre-wrap;overflow-wrap:anywhere;font-size:13px}.metadata-panel dt{font-size:12px;color:var(--muted)}.cover-editor{display:flex;align-items:center;flex-wrap:wrap;gap:15px;margin:15px 0}.cover-editor img{width:240px;max-width:100%;height:140px;object-fit:cover;border-radius:8px}.metadata-panel input[type=file]{max-width:500px}</style>
